CREATE TABLE runs (id TEXT PRIMARY KEY, visitor TEXT NOT NULL, day TEXT NOT NULL, ranking TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(visitor,day));
CREATE TABLE reviews (id TEXT PRIMARY KEY, run_id TEXT NOT NULL UNIQUE, idol_id TEXT NOT NULL, body TEXT NOT NULL, hidden INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX reviews_idol ON reviews(idol_id,hidden);
CREATE TABLE reports (review_id TEXT NOT NULL, visitor TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(review_id,visitor));
